// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_sent_sample: Option<i32>,
  pub api_observed_sample: Option<i32>,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_sent_sample(container.api_sent_sample);
  put_observed_sample(container.api_observed_sample);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  sent_sample: Option<i32>,
  observed_sample: Option<i32>)
{
  put_sent_sample(sent_sample);
  put_observed_sample(observed_sample);
}

/// setter for IN EventDataPort
pub fn put_sent_sample(value: Option<i32>)
{
  *extern_api::IN_sent_sample.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN EventDataPort
pub fn put_observed_sample(value: Option<i32>)
{
  *extern_api::IN_observed_sample.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// getter for OUT EventDataPort
pub fn get_alert_flag() -> Option<bool>
{
  return extern_api::OUT_alert_flag.lock().unwrap_or_else(|e| e.into_inner()).clone()
}
